#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <inttypes.h>

#define EMA_FAST_ALPHA 0.05
#define EMA_SLOW_ALPHA 0.002
#define MAX_BUFFER_SIZE 20
#define MIN_RUN_LENGTH 50
#define BASE_MARGIN 1.05
#define MAX_MARGIN 1.5
#define MIN_MARGIN 0.8
#define R_FOCUSED_THRESHOLD 1.15
#define R_STABLE_THRESHOLD 1.35
#define R_LOW_THRESHOLD 0.85

bool kissat_restarting(kissat *solver) {
    assert(solver->unassigned);
    if (!GET_OPTION(restart))
        return false;
    if (!solver->level)
        return false;
    if (CONFLICTS < solver->limits.restart.conflicts)
        return false;
    if (solver->stable)
        return kissat_reluctant_triggered(&solver->reluctant);

    // Step 1: Maintain EMAs
    double lbd = AVERAGE(fast_glue); // Assuming fast_glue holds the LBD of the latest learned clause
    static double fast_ema = 0.0;
    static double slow_ema = 0.0;

    fast_ema = (1 - EMA_FAST_ALPHA) * fast_ema + EMA_FAST_ALPHA * lbd;
    slow_ema = (1 - EMA_SLOW_ALPHA) * slow_ema + EMA_SLOW_ALPHA * lbd;

    // Step 2: Calculate momentum ratio
    double R = fast_ema / slow_ema;

    // Step 3: Circular buffer for fast LBD values
    static double fast_lbd_buffer[MAX_BUFFER_SIZE] = {0};
    static unsigned buffer_index = 0;
    fast_lbd_buffer[buffer_index] = lbd;
    buffer_index = (buffer_index + 1) % MAX_BUFFER_SIZE;

    // Step 4: Calculate gradient
    double sum_buffer = 0.0;
    for (unsigned i = 0; i < MAX_BUFFER_SIZE; i++) {
        sum_buffer += fast_lbd_buffer[i];
    }
    double avg_buffer = sum_buffer / MAX_BUFFER_SIZE;
    double gradient = lbd - avg_buffer;

    // Step 5: Adjust margin dynamically
    double M = BASE_MARGIN - (gradient * 2.0);
    if (M < MIN_MARGIN) M = MIN_MARGIN;
    if (M > MAX_MARGIN) M = MAX_MARGIN;

    // Step 6: Minimum run length
    if (CONFLICTS < MIN_RUN_LENGTH)
        return false;

    // Step 7: Restart conditions
    if ((solver->stable && R > R_STABLE_THRESHOLD) || (!solver->stable && R > R_FOCUSED_THRESHOLD)) {
        if (avg_buffer > slow_ema * M) {
            return true; // Trigger restart
        }
    } else if (R < R_LOW_THRESHOLD) {
        return true; // Allow for restarts
    }

    return false;
}

