#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <inttypes.h>

#define EMA_ALPHA_FAST 0.05
#define EMA_ALPHA_SLOW 0.95
#define LAMINAR_SEARCH_THRESHOLD 0.75
#define TURBULENT_SEARCH_THRESHOLD 1.1
#define LBD_VAR_EMA_LIMIT 1.0
#define TURBULENT_LBD_VAR_EMA_LIMIT 3.5
#define GRADIENT_BUFFER_SIZE 20
#define MARGIN_CLAMP_LOW 0.8
#define MARGIN_CLAMP_HIGH 1.5
#define MAX_SKIP_RESTARTS 7

bool kissat_restarting(kissat *solver) {
    assert(solver->unassigned);
    if (!GET_OPTION(restart)) return false;
    if (!solver->level) return false;
    if (CONFLICTS < solver->limits.restart.conflicts) return false;

    if (solver->stable)
        return kissat_reluctant_triggered(&solver->reluctant);

    // Step 1: Maintain EMAs
    static double fast_lbd_ema = 0.0;
    static double slow_lbd_ema = 0.0;
    static double lbd_var_ema = 0.0;
    static unsigned skip_count = 0;

    // Initialize EMAs based on the first few conflict resolutions
    if (CONFLICTS == 0) {
        fast_lbd_ema = AVERAGE(fast_glue);
        slow_lbd_ema = AVERAGE(slow_glue);
        lbd_var_ema = 0.05;  // Initial value
    }

    // Assume current_lbd is calculated or passed based on the latest conflict
    double current_lbd = AVERAGE(fast_glue); // This should be replaced with actual LBD from the conflict
    double diff = current_lbd - fast_lbd_ema;

    // Step 2: Update lbd_var_ema
    lbd_var_ema = EMA_ALPHA_SLOW * lbd_var_ema + (1 - EMA_ALPHA_SLOW) * (diff * diff);

    // Step 3: Laminar Search Condition
    bool laminar_search = (fast_lbd_ema < LAMINAR_SEARCH_THRESHOLD * slow_lbd_ema) && (lbd_var_ema < LBD_VAR_EMA_LIMIT);

    // Step 4: Turbulent Search Condition
    bool turbulent_search = (fast_lbd_ema > TURBULENT_SEARCH_THRESHOLD * slow_lbd_ema) && (lbd_var_ema > TURBULENT_LBD_VAR_EMA_LIMIT);

    // Step 5: Calculate gradient
    static double gradient_buffer[GRADIENT_BUFFER_SIZE] = {0};
    static unsigned gradient_index = 0;
    double gradient = 0.0;

    gradient_buffer[gradient_index] = fast_lbd_ema;
    gradient_index = (gradient_index + 1) % GRADIENT_BUFFER_SIZE;

    if (gradient_index == 0) {
        double sum = 0.0;
        for (unsigned i = 0; i < GRADIENT_BUFFER_SIZE; i++) {
            sum += gradient_buffer[i];
        }
        gradient = sum / GRADIENT_BUFFER_SIZE;
    }

    // Step 6: Adjust margin M
    double M = (100.0 + GET_OPTION(restartmargin)) / 100.0;
    M -= (gradient * 2.0);
    if (M < MARGIN_CLAMP_LOW) M = MARGIN_CLAMP_LOW;
    if (M > MARGIN_CLAMP_HIGH) M = MARGIN_CLAMP_HIGH;

    // Step 7: Check standard restart condition
    if (M < fast_lbd_ema) {
        if (laminar_search) {
            if (skip_count < MAX_SKIP_RESTARTS) {
                skip_count++;
                return false; // Skip restart
            }
        }
    }

    // Step 8: Force restart on turbulent search
    if (turbulent_search) {
        return true; // Force restart
    }

    return false; // Default case
}
